/**
 * MCA v0.1 and v0.2 conformance tests against test/vectors/ (regenerated by
 * gen-vectors.js immediately before this file runs, via `npm test`).
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { verifyRecord, verifyChain, verifyCheckpoint, verifyInclusion, verifyWitness } from "../src/verify.js";
import { keyIdFromPublicKeyPem, recordHash, hashCanonical, checkpointBody, checkpointHash } from "../src/hash.js";
import { generateKeyPairSync, sign as cryptoSign } from "node:crypto";
import { execFileSync, spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { canonicalize } from "../src/canonicalize.js";

const vectors = join(dirname(fileURLToPath(import.meta.url)), "vectors");
const readJson = (n) => JSON.parse(readFileSync(join(vectors, n), "utf8"));
const readJsonl = (n) =>
  readFileSync(join(vectors, n), "utf8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l));

const chain = readJsonl("chain-valid.jsonl");
const checkpoint = readJson("checkpoint-valid.json");
const forgedCp = readJson("checkpoint-forged.json");
const pubPem = readFileSync(join(vectors, "log.pub.pem"), "utf8");
const inclusionRecord = readJson("inclusion-record.json");
const inclusionPath = readJson("inclusion-path.json");

test("valid chain is VALID", () => {
  const r = verifyChain(chain);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
});

test("tampered chain is INVALID with a broken-link reason", () => {
  const r = verifyChain(readJsonl("chain-tampered.jsonl"));
  assert.equal(r.result, "INVALID");
  assert.ok(
    r.reasons.some((x) => x.startsWith("broken-link")),
    `expected broken-link reason, got: ${r.reasons.join("; ")}`,
  );
});

test("gap in sequence is detected", () => {
  const r = verifyChain(readJsonl("chain-gap.jsonl"));
  assert.equal(r.result, "INVALID");
  assert.ok(
    r.reasons.some((x) => x.startsWith("gap:")),
    `expected gap reason, got: ${r.reasons.join("; ")}`,
  );
});

test("record plus matching evidence is VALID", () => {
  const r = verifyRecord(inclusionRecord, readJson("evidence-3.json"));
  assert.equal(r.result, "VALID", r.reasons.join("; "));
});

test("record plus wrong evidence is INVALID", () => {
  const wrong = { rail_receipt: { rail: "x402", tx: "0xFFFF", amount: "999.00", currency: "USD" } };
  const r = verifyRecord(inclusionRecord, wrong);
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.some((x) => x.startsWith("evidence-mismatch")));
});

test("checkpoint verifies via ed25519 and surfaces UNWITNESSED", () => {
  const r = verifyCheckpoint(checkpoint, chain, null, pubPem);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
  assert.ok(r.reasons.some((x) => x.startsWith("UNWITNESSED")), `missing UNWITNESSED caveat: ${r.reasons}`);
});

test("forged checkpoint (wrong merkle_root, original signature) is INVALID", () => {
  const r = verifyCheckpoint(forgedCp, chain, null, pubPem);
  assert.equal(r.result, "INVALID");
  assert.ok(
    r.reasons.some((x) => x === "merkle-root-mismatch") || r.reasons.some((x) => x.startsWith("bad-signature")),
    `expected merkle/signature failure, got: ${r.reasons.join("; ")}`,
  );
});

test("inclusion proof against the real checkpoint root is VALID", () => {
  const r = verifyInclusion(inclusionRecord, inclusionPath, checkpoint);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
});

test("inclusion proof against the forged root is INVALID", () => {
  const r = verifyInclusion(inclusionRecord, inclusionPath, forgedCp);
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.some((x) => x.startsWith("inclusion-proof-failed")));
});

test("invalid subject_type is INVALID", () => {
  const bad = JSON.parse(JSON.stringify(inclusionRecord));
  bad.subject_type = "robot";
  const r = verifyRecord(bad);
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.some((x) => x.startsWith("bad-subject_type")));
});

// ─── Addendum 0.1.1: witnesses, wrapped inclusion proofs, production vectors ──

const witnessedCp = readJson("checkpoint-witnessed.json");
const witnessForgedCp = readJson("checkpoint-witness-forged.json");
const witnessPem = readFileSync(join(vectors, "witness.pub.pem"), "utf8");
const witnessId = witnessedCp.witnesses[0].witness_id;
const witnessKeyId = witnessedCp.witnesses[0].key_id;

test("witnessed checkpoint reports WITNESSED:<id> when the witness key is supplied", () => {
  const r = verifyCheckpoint(witnessedCp, chain, undefined, pubPem, undefined, { witnessKeys: { [witnessKeyId]: witnessPem } });
  assert.equal(r.result, "VALID", r.reasons.join("; "));
  assert.ok(r.reasons.includes(`WITNESSED:${witnessId}`));
  assert.ok(!r.reasons.includes("UNWITNESSED"));
});

test("witnessed checkpoint reports WITNESS_UNVERIFIED:<id> when no witness key is supplied (never UNWITNESSED)", () => {
  const r = verifyCheckpoint(witnessedCp, chain, undefined, pubPem);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
  assert.ok(r.reasons.includes(`WITNESS_UNVERIFIED:${witnessId}`));
  assert.ok(!r.reasons.includes("UNWITNESSED"));
});

test("a witness cosignature over other bytes makes the checkpoint INVALID when its key is supplied", () => {
  const r = verifyCheckpoint(witnessForgedCp, chain, undefined, pubPem, undefined, { witnessKeys: { [witnessId]: witnessPem } });
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.some((x) => x.startsWith(`bad-witness-signature:${witnessId}`)));
  assert.equal(verifyWitness(witnessForgedCp, witnessForgedCp.witnesses[0], witnessPem).result, "INVALID");
  assert.equal(verifyWitness(witnessedCp, witnessedCp.witnesses[0], witnessPem).result, "VALID");
});

test("witness entries do not disturb the operator signature", () => {
  const r = verifyCheckpoint(witnessedCp, chain, undefined, pubPem);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
});

test("key_id derives from the SPKI DER: ed25519:<first 16 hex of sha256>", () => {
  assert.match(keyIdFromPublicKeyPem(witnessPem), /^ed25519:[0-9a-f]{16}$/);
  assert.equal(keyIdFromPublicKeyPem(witnessPem), witnessKeyId);
});

test("inclusion proof in a log's object form verifies, and a mismatched wrapper is INVALID", () => {
  const wrapped = readJson("inclusion-wrapped.json");
  assert.equal(verifyInclusion(inclusionRecord, wrapped, checkpoint).result, "VALID");
  const wrongRoot = { ...wrapped, merkle_root: "0".repeat(64) };
  const r = verifyInclusion(inclusionRecord, wrongRoot, checkpoint);
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.includes("proof-checkpoint-mismatch:merkle_root"));
  const wrongRecord = { ...wrapped, record_hash: "0".repeat(64) };
  assert.ok(verifyInclusion(inclusionRecord, wrongRecord, checkpoint).reasons.includes("proof-record-mismatch:record_hash"));
});

// Production vectors: captured from log.iondra.com/main/record-hash-v1 on 2026-11-04
// (checkpoints rh1-cp-5..8, records seq 0..5, operator key, one served inclusion proof).
const prod = (n) => join(vectors, "production", n);
const prodJson = (n) => JSON.parse(readFileSync(prod(n), "utf8"));
const prodJsonl = (n) => readFileSync(prod(n), "utf8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l));
const prodPem = readFileSync(prod("log.pub.pem"), "utf8");

test("production: chain seq 0..5 is VALID", () => {
  const r = verifyChain(prodJsonl("chain-seq-0-5.jsonl"));
  assert.equal(r.result, "VALID", r.reasons.join("; "));
});

test("production: checkpoints rh1-cp-5..8 verify in sequence against the operator key", () => {
  let prev;
  for (const i of [5, 6, 7, 8]) {
    const cp = prodJson(`checkpoint-rh1-cp-${i}.json`);
    const r = verifyCheckpoint(cp, prodJsonl(`records-rh1-cp-${i}.jsonl`), prev, prodPem);
    assert.equal(r.result, "VALID", `cp-${i}: ${r.reasons.join("; ")}`);
    assert.deepEqual(r.reasons, ["UNWITNESSED"], `cp-${i} caveats`);
    prev = cp;
  }
});

test("production: operator key_id in log.json derives from the published key", () => {
  const log = prodJson("log.json");
  assert.equal(keyIdFromPublicKeyPem(log.public_key_pem), log.key_id);
  assert.equal(log.key_id, prodJson("checkpoint-rh1-cp-8.json").signature.key_id);
});

test("production: the served inclusion proof (object form) verifies the seq-4 commerce leaf under rh1-cp-8", () => {
  const rec = prodJson("record-seq-4.json");
  assert.equal(rec.action, "commerce.payment.executed");
  assert.equal(rec.commerce.rail, "x402");
  assert.equal(rec.record_hash, recordHash(rec), "record carries its own record_hash, excluded from hashing");
  const r = verifyInclusion(rec, prodJson("inclusion-seq-4-wrapped.json"), prodJson("checkpoint-rh1-cp-8.json"));
  assert.equal(r.result, "VALID", r.reasons.join("; "));
});

// ─── v0.2: the checkpoint chain link (spec §6.3, mca-spec issue #2) ──────────
//
// v0.1 linked checkpoints by hashing the WHOLE previous checkpoint, mutable
// `witnesses` array included, so the link value depended on when the previous
// checkpoint was fetched. v0.2 links by checkpoint_hash: the hash of the bytes
// the operator signed. The form is selected by the linking checkpoint's own
// mca_version.

const v02 = (n) => join(vectors, "v02", n);
const v02Json = (n) => JSON.parse(readFileSync(v02(n), "utf8"));
const v02Jsonl = (n) => readFileSync(v02(n), "utf8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l));
const v02LogPem = readFileSync(v02("log.pub.pem"), "utf8");
const v02Witnesses = {
  "witness.a.example": readFileSync(v02("witness-a.pub.pem"), "utf8"),
  "witness.b.example": readFileSync(v02("witness-b.pub.pem"), "utf8"),
};
const expected = v02Json("expected.json");

for (const c of expected.cases) {
  test(`v0.2 vectors: ${c.name}`, () => {
    const r = verifyCheckpoint(v02Json(c.cp), v02Jsonl(c.records), c.prev ? v02Json(c.prev) : undefined, v02LogPem, undefined, { witnessKeys: v02Witnesses });
    assert.equal(r.result, c.result, r.reasons.join("; "));
    assert.deepEqual(r.reasons, c.reasons);
  });
}

test("checkpoint_hash: every copy of one checkpoint has the same hash, whatever its witnesses", () => {
  const want = expected.checkpoint_hash["t-cp-3"];
  for (const f of ["cp-3.emitted.json", "cp-3.served.json", "cp-3.no-witnesses-member.json", "cp-3.empty-witnesses.json", "cp-3.reordered.json"])
    assert.equal(checkpointHash(v02Json(f)), want, f);
  // ...and it does not depend on the signature object either.
  const cp = v02Json("cp-3.emitted.json");
  assert.equal(checkpointHash({ ...cp, signature: { alg: "ed25519", key_id: "ed25519:0000000000000000", sig: "AAAA" } }), want);
});

test("checkpoint_hash: any change to the signed body changes it", () => {
  const cp = v02Json("cp-3.emitted.json");
  const want = checkpointHash(cp);
  const changed = [
    { ...cp, merkle_root: "0".repeat(64) },
    { ...cp, timestamp: "2026-01-15T13:21:00.000Z" },
    { ...cp, range: { from_seq: 3, to_seq: 4 } },
    { ...cp, checkpoint_id: "t-cp-3b" },
    { ...cp, notes: { sealed_history: true } },
    { ...cp, some_future_member: 1 }, // unknown members are part of the body
  ];
  for (const [i, c] of changed.entries()) assert.notEqual(checkpointHash(c), want, `variant ${i}`);
});

test("checkpoint body: only the top-level `signature` and `witnesses` are left out", () => {
  const cp = { ...v02Json("cp-3.emitted.json"), notes: { witnesses: ["kept"], signature: "kept" }, some_future_member: { a: 1 } };
  const body = checkpointBody(cp);
  assert.ok(!("signature" in body) && !("witnesses" in body));
  assert.deepEqual(body.notes, { witnesses: ["kept"], signature: "kept" });
  assert.deepEqual(body.some_future_member, { a: 1 });
  assert.equal(Object.keys(body).length, Object.keys(cp).length - 2);
});

test("checkpoint_hash is the hash of exactly the bytes the operator signed and the witnesses cosigned", () => {
  const cp = v02Json("cp-3.served.json");
  assert.equal(checkpointHash(cp), hashCanonical(checkpointBody(cp)));
  // The signatures verify over those same bytes: nothing else is needed to check them.
  for (const w of cp.witnesses) assert.equal(verifyWitness(cp, w, v02Witnesses[w.witness_id]).result, "VALID");
});

test("cached copy: a copy taken before a witness merged is the same checkpoint (same checkpoint_hash) as the served one", () => {
  assert.equal(checkpointHash(v02Json("cp-1.cached-early.json")), checkpointHash(v02Json("cp-1.served.json")));
  assert.notEqual(hashCanonical(v02Json("cp-1.cached-early.json")), hashCanonical(v02Json("cp-1.served.json")), "the v0.1 full form differs");
});

test("a whole chain that crosses the 0.1 to 0.2 transition verifies link by link, as emitted and as served later", () => {
  for (const state of ["emitted", "served"]) {
    let prev;
    for (const n of [1, 2, 3, 4]) {
      const cp = v02Json(`cp-${n}.${state}.json`);
      const r = verifyCheckpoint(cp, v02Jsonl(`records-cp-${n}.jsonl`), prev, v02LogPem, undefined, { witnessKeys: v02Witnesses });
      assert.equal(r.result, "VALID", `${state} cp-${n}: ${r.reasons.join("; ")}`);
      prev = cp;
    }
  }
});

test("0.1 link with late witnesses: more than one late entry, and an entry merged ahead of an earlier one", () => {
  const cp2 = v02Json("cp-2.emitted.json");
  const one = v02Json("cp-1.emitted.json");
  const [a] = one.witnesses;
  const b = v02Json("cp-1.served.json").witnesses[1];
  const c = { ...b, witness_id: "witness.c.example" }; // not verified here; only the link is under test
  const run = (witnesses) => verifyCheckpoint(cp2, v02Jsonl("records-cp-2.jsonl"), { ...one, witnesses }, v02LogPem);
  assert.deepEqual(run([a, b, c]).reasons.filter((x) => x.startsWith("PREV_")), ["PREV_WITNESS_ADDED_AFTER_LINK:witness.b.example", "PREV_WITNESS_ADDED_AFTER_LINK:witness.c.example"]);
  assert.equal(run([a, b, c]).result, "VALID");
  assert.deepEqual(run([b, a]).reasons.filter((x) => x.startsWith("PREV_")), ["PREV_WITNESS_ADDED_AFTER_LINK:witness.b.example"]);
  // An entry the link DID cover was altered: no subset reproduces the link.
  const r = run([{ ...a, timestamp: "2026-01-15T12:11:00.001Z" }, b]);
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.includes("checkpoint-chain-broken:prev_checkpoint_hash-mismatch"));
});

test("0.1 link with late witnesses: a long witness list falls back to prefixes and still resolves", () => {
  const cp2 = v02Json("cp-2.emitted.json");
  const one = v02Json("cp-1.emitted.json");
  const late = Array.from({ length: 20 }, (_, i) => ({ ...one.witnesses[0], witness_id: `witness.late-${i}.example` }));
  const r = verifyCheckpoint(cp2, v02Jsonl("records-cp-2.jsonl"), { ...one, witnesses: [...one.witnesses, ...late] }, v02LogPem);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
  assert.equal(r.reasons.filter((x) => x.startsWith("PREV_WITNESS_ADDED_AFTER_LINK:")).length, 20);
});

test("a late witness on a 0.1 predecessor never hides a changed body", () => {
  const cp2 = v02Json("cp-2.emitted.json");
  const served = v02Json("cp-1.served.json");
  const r = verifyCheckpoint(cp2, v02Jsonl("records-cp-2.jsonl"), { ...served, merkle_root: "0".repeat(64) }, v02LogPem);
  assert.equal(r.result, "INVALID");
  assert.deepEqual(r.reasons, ["checkpoint-chain-broken:prev_checkpoint_hash-mismatch"]);
});

test("checkpoint versions: 0.1 and 0.2 are accepted, anything else is refused", () => {
  const cp = { ...v02Json("cp-4.emitted.json"), mca_version: "0.3" };
  const r = verifyCheckpoint(cp, v02Jsonl("records-cp-4.jsonl"), undefined, v02LogPem);
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.includes("unsupported-version:0.3"));
});

test("0.2 genesis checkpoint: all-zero link, no UNANCHORED caveat", () => {
  const { privateKey, publicKey } = generateKeyPairSync("ed25519");
  const pem = publicKey.export({ type: "spki", format: "pem" });
  const body = { ...checkpointBody(v02Json("cp-1.emitted.json")), mca_version: "0.2" };
  const cp = { ...body, signature: { alg: "ed25519", key_id: keyIdFromPublicKeyPem(pem), sig: cryptoSign(null, Buffer.from(canonicalize(body), "utf8"), privateKey).toString("base64url") }, witnesses: [] };
  const r = verifyCheckpoint(cp, v02Jsonl("records-cp-1.jsonl"), undefined, pem);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
  assert.deepEqual(r.reasons, ["UNWITNESSED"]);
});

test("CLI: `mca checkpoint-hash` prints the checkpoint_hash, and the same one for every copy", () => {
  const cli = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "cli.js");
  const run = (f) => execFileSync(process.execPath, [cli, "checkpoint-hash", v02(f)], { encoding: "utf8" }).trim();
  assert.equal(run("cp-3.emitted.json"), expected.checkpoint_hash["t-cp-3"]);
  assert.equal(run("cp-3.served.json"), expected.checkpoint_hash["t-cp-3"]);
});

// ─── Production, captured 2026-11-18: rh1-cp-9..15 (the witnessed part of the log) ──
const prodWitnesses = {
  "witness.iondra.operator": readFileSync(prod("witness-operator.pub.pem"), "utf8"),
  "witness.cloudflare.iondra-0": readFileSync(prod("witness-cloudflare.pub.pem"), "utf8"),
};
const OPW = "WITNESSED:witness.iondra.operator", CFW = "WITNESSED:witness.cloudflare.iondra-0";

test("production: every checkpoint rh1-cp-5..15 still verifies in sequence, with the reasons 0.1.1 reports", () => {
  let prev;
  for (let i = 5; i <= 15; i++) {
    const cp = prodJson(`checkpoint-rh1-cp-${i}.json`);
    const r = verifyCheckpoint(cp, prodJsonl(`records-rh1-cp-${i}.jsonl`), prev, prodPem, undefined, { witnessKeys: prodWitnesses });
    assert.equal(r.result, "VALID", `cp-${i}: ${r.reasons.join("; ")}`);
    assert.deepEqual(r.reasons, i <= 8 ? ["UNWITNESSED"] : i === 9 ? [OPW] : [OPW, CFW], `cp-${i} reasons`);
    assert.equal(cp.mca_version, "0.1");
    prev = cp;
  }
});

test("production: the 5 November failure of mca-spec issue #2, reproduced from the public checkpoints", () => {
  const cp10 = prodJson("checkpoint-rh1-cp-10.json");
  const cp11 = prodJson("checkpoint-rh1-cp-11.json");
  // What a witness held on 5 November: rh1-cp-10 before the Cloudflare cosignature was merged.
  const cp10Cached = { ...cp10, witnesses: cp10.witnesses.slice(0, 1) };
  assert.equal(cp11.prev_checkpoint_hash, hashCanonical(cp10), "the link covers rh1-cp-10 with both witness entries");
  assert.notEqual(cp11.prev_checkpoint_hash, hashCanonical(cp10Cached));
  const r = verifyCheckpoint(cp11, prodJsonl("records-rh1-cp-11.jsonl"), cp10Cached, prodPem);
  assert.equal(r.result, "INVALID", "a 0.1 link cannot be checked from the earlier copy");
  // The two copies are nevertheless the same checkpoint: under v0.2 they would link identically.
  assert.equal(checkpointHash(cp10Cached), checkpointHash(cp10));
});

test("production: if a witness were merged into rh1-cp-9 today, rh1-cp-10 would still verify (0.1.1 reports a broken chain)", () => {
  const cp9 = prodJson("checkpoint-rh1-cp-9.json");
  const cp10 = prodJson("checkpoint-rh1-cp-10.json");
  assert.equal(cp9.witnesses.length, 1, "rh1-cp-9 carries the operator entry only");
  const w = generateKeyPairSync("ed25519");
  const pem = w.publicKey.export({ type: "spki", format: "pem" });
  const late = { witness_id: "witness.test.late", key_id: keyIdFromPublicKeyPem(pem), alg: "ed25519", timestamp: "2026-11-18T12:00:00.000Z",
    sig: cryptoSign(null, Buffer.from(canonicalize(checkpointBody(cp9)), "utf8"), w.privateKey).toString("base64url") };
  const cp9Later = { ...cp9, witnesses: [...cp9.witnesses, late] };
  assert.equal(verifyWitness(cp9Later, late, pem).result, "VALID", "the late cosignature is a real one over rh1-cp-9");
  assert.notEqual(hashCanonical(cp9Later), cp10.prev_checkpoint_hash, "the 0.1 full form no longer matches");
  const r = verifyCheckpoint(cp10, prodJsonl("records-rh1-cp-10.jsonl"), cp9Later, prodPem, undefined, { witnessKeys: prodWitnesses });
  assert.equal(r.result, "VALID", r.reasons.join("; "));
  assert.deepEqual(r.reasons, ["PREV_WITNESS_ADDED_AFTER_LINK:witness.test.late", OPW, CFW]);
});

test("production: a checkpoint of the legacy generation cannot stand in as the previous checkpoint of the active one", () => {
  const cp5 = prodJson("checkpoint-rh1-cp-5.json");
  assert.equal(cp5.prev_checkpoint_hash, "0".repeat(64), "the active generation starts its own chain at genesis");
  const legacy = { ...checkpointBody(cp5), log_id: "log.iondra.com/main", checkpoint_id: "cp-4" };
  const r = verifyCheckpoint(prodJson("checkpoint-rh1-cp-6.json"), prodJsonl("records-rh1-cp-6.jsonl"), legacy, prodPem);
  assert.equal(r.result, "INVALID");
  assert.deepEqual(r.reasons, ["checkpoint-chain-broken:prev-checkpoint-is-from-another-log"]);
});

// ─── Review follow-ups: bounded witness search, inputs with no canonical form ──

test("0.1 link, more than 12 witness entries, a late entry ahead of the covered one: INVALID, and the reason says the search was incomplete", () => {
  const cp2 = v02Json("cp-2.emitted.json");
  const one = v02Json("cp-1.emitted.json");
  const [a] = one.witnesses;
  const late = (i) => ({ ...a, witness_id: `witness.late-${i}.example` });
  // The link covers [a]. The served copy holds [late-0, a, late-1 .. late-11]: 13 entries, so only leading runs are tried.
  const witnesses = [late(0), a, ...Array.from({ length: 11 }, (_, i) => late(i + 1))];
  const r = verifyCheckpoint(cp2, v02Jsonl("records-cp-2.jsonl"), { ...one, witnesses }, v02LogPem);
  assert.equal(r.result, "INVALID");
  assert.deepEqual(r.reasons, ["checkpoint-chain-broken:prev_checkpoint_hash-mismatch:witness-search-incomplete:13-entries"]);
  // With 12 entries the same arrangement is searched in full and resolves.
  const r12 = verifyCheckpoint(cp2, v02Jsonl("records-cp-2.jsonl"), { ...one, witnesses: witnesses.slice(0, 12) }, v02LogPem);
  assert.equal(r12.result, "VALID", r12.reasons.join("; "));
  assert.equal(r12.reasons.filter((x) => x.startsWith("PREV_WITNESS_ADDED_AFTER_LINK:")).length, 11);
});

test("0.1 link, a very long witness list: no search is attempted and the reason says so", () => {
  const cp2 = v02Json("cp-2.emitted.json");
  const one = v02Json("cp-1.emitted.json");
  const witnesses = [...one.witnesses, ...Array.from({ length: 20000 }, (_, i) => ({ ...one.witnesses[0], witness_id: `witness.late-${i}.example` }))];
  const started = process.hrtime.bigint();
  const r = verifyCheckpoint(cp2, v02Jsonl("records-cp-2.jsonl"), { ...one, witnesses }, v02LogPem);
  const ms = Number(process.hrtime.bigint() - started) / 1e6;
  assert.equal(r.result, "INVALID");
  assert.deepEqual(r.reasons, ["checkpoint-chain-broken:prev_checkpoint_hash-mismatch:witness-search-incomplete:20001-entries"]);
  assert.ok(ms < 2000, `bounded work: took ${ms.toFixed(0)} ms`);
  // 64 entries is the last size still searched (leading runs only).
  const w64 = [...one.witnesses, ...witnesses.slice(1, 64)];
  assert.equal(verifyCheckpoint(cp2, v02Jsonl("records-cp-2.jsonl"), { ...one, witnesses: w64 }, v02LogPem).result, "VALID");
  const w65 = [...one.witnesses, ...witnesses.slice(1, 65)];
  assert.equal(verifyCheckpoint(cp2, v02Jsonl("records-cp-2.jsonl"), { ...one, witnesses: w65 }, v02LogPem).result, "INVALID");
});

test("a 0.2 checkpoint in the wrong form costs one comparison to diagnose, however many witnesses the previous checkpoint has", () => {
  const cp = v02Json("cp-4.full-form-link.json");
  const prev = v02Json("cp-3.emitted.json");
  const many = { ...prev, witnesses: [...prev.witnesses, ...Array.from({ length: 20000 }, (_, i) => ({ ...prev.witnesses[0], witness_id: `witness.x-${i}.example` }))] };
  const r = verifyCheckpoint(cp, v02Jsonl("records-cp-4.jsonl"), many, v02LogPem);
  assert.equal(r.result, "INVALID");
  assert.deepEqual(r.reasons, ["checkpoint-chain-broken:prev_checkpoint_hash-mismatch"]);
});

test("0.2 link: a witness entry with no canonical form in the previous checkpoint does not affect the link", () => {
  const cp4 = v02Json("cp-4.emitted.json");
  const prev = v02Json("cp-3.emitted.json");
  const odd = { ...prev, witnesses: [...prev.witnesses, { witness_id: "witness.odd.example", weight: Infinity }] }; // what JSON.parse makes of 1e400
  const r = verifyCheckpoint(cp4, v02Jsonl("records-cp-4.jsonl"), odd, v02LogPem);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
});

test("0.1 link: an uncovered witness entry with no canonical form is set aside like any other; a body with none is reported", () => {
  const cp2 = v02Json("cp-2.emitted.json");
  const one = v02Json("cp-1.emitted.json");
  const odd = { ...one, witnesses: [...one.witnesses, { witness_id: "witness.odd.example", weight: Infinity }] };
  const r = verifyCheckpoint(cp2, v02Jsonl("records-cp-2.jsonl"), odd, v02LogPem);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
  assert.ok(r.reasons.includes("PREV_WITNESS_ADDED_AFTER_LINK:witness.odd.example"));
  const badBody = verifyCheckpoint(cp2, v02Jsonl("records-cp-2.jsonl"), { ...one, notes: { n: Infinity } }, v02LogPem);
  assert.equal(badBody.result, "INVALID");
  assert.ok(badBody.reasons[0].startsWith("prev-checkpoint-not-canonicalizable:"));
});

test("0.1 link over an empty witnesses array still verifies after an entry is merged (and over an absent member too)", () => {
  // The case of mca-spec PR 3 review: the link was made when the previous checkpoint carried `"witnesses": []`.
  const { privateKey, publicKey } = generateKeyPairSync("ed25519");
  const pem = publicKey.export({ type: "spki", format: "pem" });
  const sign = (body) => ({ ...body, signature: { alg: "ed25519", key_id: keyIdFromPublicKeyPem(pem), sig: cryptoSign(null, Buffer.from(canonicalize(body), "utf8"), privateKey).toString("base64url") } });
  const prevSigned = sign(checkpointBody(v02Json("cp-1.emitted.json")));
  const entry = v02Json("cp-1.emitted.json").witnesses[0];
  for (const [label, asLinked] of [["empty array", { ...prevSigned, witnesses: [] }], ["absent member", prevSigned]]) {
    const cp = { ...sign({ ...checkpointBody(v02Json("cp-2.emitted.json")), prev_checkpoint_hash: hashCanonical(asLinked) }), witnesses: [] };
    const r = verifyCheckpoint(cp, v02Jsonl("records-cp-2.jsonl"), { ...prevSigned, witnesses: [entry] }, pem);
    assert.equal(r.result, "VALID", `${label}: ${r.reasons.join("; ")}`);
    assert.deepEqual(r.reasons, ["PREV_WITNESS_ADDED_AFTER_LINK:witness.a.example", "UNWITNESSED"], label);
  }
});

test("a record with no canonical form is INVALID with its position, not an exception", () => {
  const recs = v02Jsonl("records-cp-4.jsonl");
  const r = verifyCheckpoint(v02Json("cp-4.emitted.json"), [{ ...recs[0], extra: Infinity }], v02Json("cp-3.emitted.json"), v02LogPem);
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.some((x) => x.startsWith("record-not-canonicalizable:position-0:")), r.reasons.join("; "));
});

test("CLI: `mca checkpoint-hash` on a checkpoint with no canonical form is an input error (exit 2), not a stack trace", () => {
  const cli = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "cli.js");
  const dir = mkdtempSync(join(tmpdir(), "mca-"));
  const f = join(dir, "cp.json");
  writeFileSync(f, readFileSync(v02("cp-3.emitted.json"), "utf8").replace('"hash_alg"', '"weight": 1e400, "hash_alg"'));
  const r = spawnSync(process.execPath, [cli, "checkpoint-hash", f], { encoding: "utf8" });
  rmSync(dir, { recursive: true, force: true });
  assert.equal(r.status, 2);
  assert.match(r.stderr, /^mca: error: .* has no canonical form: /);
  assert.equal(r.stdout, "");
});
